mapper.insert:
            INSERT INTO sale 
        	(
        	cstmr_id
        	,shop_id
			,coupon_id
			,ogn_price
			,pay_cash
			,pay_card
			,email
			,phone
			,addr
			,datetime
			,regtime
        	) 
        VALUES (
        	(select cstmr_id from cstmr where cstmr_login_id = #{UserID})
        	, #{shopNumber}
        	, #{couponId}
        	, #{ognPrice}
        	, #{payCash}
        	, #{payCard}
        	, #{UserEmail}
        	, #{UserPhone}
        	, #{userAddr}
        	, DATE_FORMAT(now(),'%Y%m%d')
        	, now()
        	);

            SELECT LAST_INSERT_ID();

mapper.select:
SELECT COUNT(*) 
FROM sale
WHERE sale_name=#{saleName}

SELECT * FROM( SELECT A.sale_id ,(select shop_name from shop where shop_id=A.shop_id) shop_name ,(select cstmr_name from cstmr where cstmr_id=A.cstmr_id) userName ,addr userAddr ,phone userPhone ,datetime ,regtime ,result ,(select sum(prc) from salePrdct where sale_id=A.sale_id) price FROM sale A WHERE datetime between ${startTime} and ${endTime}
and (result = '0000' or result = '0' or result='sucess')
and (result = #{result})
) B
and ( userName = #{cstmrName})
order by datetime desc,regtime desc

select datetime ,(select shop_name from shop where shop_id=Y.shop_id) shop_name ,sum(pay_cash) pay_cash ,sum(pay_card) pay_card ,sum(price) total ,sum(frame_prc) frame_prc ,sum(lens_prc) lens_prc from( SELECT Z.sale_id ,pay_cash ,pay_card ,shop_id ,result ,(select sum(prc) from salePrdct where sale_id=Z.sale_id) price ,(select sum(prc) from salePrdct A, prdct B where A.prdct_id = B.prdct_id and A.sale_id=Z.sale_id and B.prdct_ty_cd = '00300001') frame_prc ,(select sum(prc) from salePrdct A, prdct B where A.prdct_id = B.prdct_id and A.sale_id=Z.sale_id and B.prdct_ty_cd = '00300002') lens_prc ,datetime FROM sale Z WHERE datetime between ${startTime} and ${endTime}
AND shop_id = #{shopId}
) Y
group by datetime
group by shop_name

mapper.update:
UPDATE sale SET
	result		= #{CJSResultCode}
	,result_msg = #{CJSResultMessage}
	,pay_id		= #{CJSPayID}
	,trade_id	= #{CJSTradeID}
	,pay_date	= #{CJSPaydate}
	,pgctrl		= #{Crd_pgctrl_Cd_p}
WHERE
	sale_id 			= #{saleId}

mapper.select:
SELECT shop_name, shop_id
FROM shop ORDER BY shop_name ASC
where shop_id = #{shopId}
